use fixture::{ParseVersionError, Version};
use std::str::FromStr;

fn assert_error_type<E: std::error::Error + Clone + PartialEq + Eq + 'static>() {}

#[test]
fn displays_components() {
    assert_eq!(Version::new(1, 20, 3).to_string(), "1.20.3");
    assert_eq!(Version::new(0, 0, 0).to_string(), "0.0.0");
    assert_eq!(format!("v{}", Version::new(4, 5, 6)), "v4.5.6");
}

#[test]
fn parses_valid_versions() {
    assert_eq!("1.2.3".parse::<Version>(), Ok(Version::new(1, 2, 3)));
    assert_eq!(Version::from_str("0.10.0"), Ok(Version::new(0, 10, 0)));
    assert_eq!(
        "18446744073709551615.0.1".parse::<Version>(),
        Ok(Version::new(u64::MAX, 0, 1))
    );
}

#[test]
fn rejects_invalid_versions() {
    for text in [
        "", "1", "1.2", "1.2.3.4", "1..3", ".1.2", "1.2.", "01.2.3", "1.02.3", "1.2.00",
        "1.2.x", " 1.2.3", "1.2.3 ", "v1.2.3", "+1.2.3", "1.+2.3", "-1.2.3", "1.2.3-alpha",
        "18446744073709551616.0.0", "1.2.٣", "１.2.3",
    ] {
        assert!(text.parse::<Version>().is_err(), "{text:?} must be rejected");
    }
}

#[test]
fn round_trips() {
    for version in [
        Version::new(0, 0, 0),
        Version::new(1, 0, 10),
        Version::new(12, 345, 6789),
        Version::new(u64::MAX, u64::MAX, u64::MAX),
    ] {
        assert_eq!(version.to_string().parse::<Version>(), Ok(version));
    }
}

#[test]
fn orders_numerically() {
    assert!(Version::new(1, 10, 0) > Version::new(1, 9, 9));
    assert!(Version::new(2, 0, 0) > Version::new(1, 99, 99));
    assert!(Version::new(1, 2, 3) < Version::new(1, 2, 4));
    assert_eq!(Version::new(1, 2, 3).cmp(&Version::new(1, 2, 3)), std::cmp::Ordering::Equal);
    let mut versions: Vec<Version> = ["1.10.0", "1.2.0", "0.9.9", "1.2.10", "1.2.9"]
        .iter()
        .map(|text| text.parse().unwrap())
        .collect();
    versions.sort();
    let sorted: Vec<String> = versions.iter().map(ToString::to_string).collect();
    assert_eq!(sorted, ["0.9.9", "1.2.0", "1.2.9", "1.2.10", "1.10.0"]);
}

#[test]
fn error_is_a_standard_error() {
    assert_error_type::<ParseVersionError>();
    let error = "nope".parse::<Version>().unwrap_err();
    assert!(!error.to_string().is_empty());
    let boxed: Box<dyn std::error::Error> = Box::new(error.clone());
    assert!(!boxed.to_string().is_empty());
    assert_eq!(error.clone(), error);
    assert_eq!(Version::new(1, 2, 3).bump_patch(), Version::new(1, 2, 4));
}
